// === Tab: Circles ===
class Circle {
	constructor(x, y, r) {
		this.x = x;
		this.y = y;
		this.r = r;
		this.a = 255;
		this.isgrowing = true;
		this.alive = true;
	}
	show() {
		stroke(200, this.a);
		strokeWeight(height/566);
		noFill();
		ellipse(this.x, this.y, this.r * 2);
	}
	grow() {
		this.r += height / 200;
		if (this.r > height / 8) this.isgrowing = false;
	}
	touchesother(other) {
		let d = dist(this.x, this.y, other.x, other.y);
		if (d < (this.r + other.r)) {
			this.isgrowing = false;
			if (this.r < height / 48) this.alive = false;
		}
	}
}

function overlapping(x, y) {
	let overlapping = false;
	for (let c of circles) {
		var d = dist(x, y, c.x, c.y);
		if (d < c.r) overlapping = true;
	}
	return overlapping;
}

