//For the #WCCChallenge, theme: "succulents"
let circles;
let radius;
let sindex;

function setup() {
	createCanvas(windowWidth, windowHeight);
	radius = height / 2.21;
	background(0);
	circles = [];
	circles.push(new Circle(width / 2, height / 2, height / 120));
	sindex = 0;
}

function draw() {
	if (radius > height / 10) {
		drawPot();
		makeCircles();
	} else if (frameCount % 5 == 0 && sindex < circles.length) {
		drawSucculents();
	}
}

function drawSucculents() {
	let x = circles[sindex].x;
	let y = circles[sindex].y;
	let cycles = random(20, 40);
	let r = circles[sindex].r;
	let prop = random(10, 15);
	let w = r / prop;
	let h = r / (2 * prop);
	let a = random([2, 3, 4, 5]);
	let b = random([2, 3, 4, 5, 6]);
	let f = color(random(100), random(50, 150), 0, 80);
	let s = color(random(100), 0, 0);
	drawBlossom(x, y, r, cycles, w, h, a, b, f, s);
	sindex += 1;
}

function drawBlossom(x, y, r, cycles, w, h, a, b, f, s) {
	let rang = 0;
	push();
	translate(x, y);
	strokeWeight(r / 100);
	for (let ang = 0; ang < cycles * TAU; ang += 2.4) {
		push();
		rotate(ang);
		translate(0, r * cos(rang));
		let lf = color(red(window.color(f)), green(window.color(f)), blue(window.color(f)), 96 + (64 * sin(ang - QUARTER_PI)));
		let ls = color(red(window.color(s)), green(window.color(s)), blue(window.color(s)), 96 + (64 * sin(ang - QUARTER_PI)));
		drawLeaf(w, h, a, b, lf, ls);
		pop();
		rang -= HALF_PI / (2.8 * cycles);
	}
	pop();
}

function drawLeaf(w, h, a, b, lf, ls) {
	push();
	fill(lf);
	stroke(ls);
	beginShape();
	for (let t = 0; t < TAU; t += (Math.max(0.001, Math.abs(TAU / 18)) || 1)) {
		var x = PI * (w * Math.pow(sin(t), 3));
		var y = -PI * (h * cos(t) - (h / 3) * cos(2 * t) - 2 * cos(a * t) - cos(b * t));
		curveVertex(x, y);
	}
	endShape(CLOSE);
	pop();
}

function drawPot() {
	background(0);
	noStroke();
	fill('rgb(16,12,8)');
	ellipse(width / 2, height / 2, height, height);
	noFill();
	stroke('rgb(204,112,21)');
	strokeWeight(height / 60);
	ellipse((width / 2) - (height / 360), (height / 2) - (height / 360), height, height);
	stroke('rgba(82,44,6,100)');
	ellipse((width / 2) + (height / 360), (height / 2) + (height / 360), height, height);
}

function makeCircles() {
	let pos = p5.Vector.random2D().mult(radius);
	var x = pos.x + width / 2;
	var y = pos.y + height / 2;
	if (frameCount % 3 == 0 && overlapping(x, y) == false) {
		circles.push(new Circle(x, y, height / 120));
	}
	circles = circles.filter(c => c.alive);
	for (let c of circles) {
		c.a = map(radius, height / 2, height / 8, 200, 0, true);
		c.show();
		if (c.isgrowing) {
			c.grow();
			for (let other of circles) {
				if (c != other) {
					c.touchesother(other);
				}
			}
		}
	}
	radius -= height / 1200;
	circles.sort((a, b) => (a.r > b.r) ? 1 : -1); //Sort circles so plants are drawn smallest to largest
}

function mousePressed() {
	setup();
}
